user_data = {}  # user -> {"total_amount": float, "total_items": int}
tag_counts = {}  # tag -> int

for filepath in files:
    with open(filepath, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                record = json.loads(line)
                user = record['user']
                amount = record['amount']
                items = record['items']
                tags = record.get('tags', [])  # might be empty array

                # Update user totals
                if user not in user_data:
                    user_data[user] = {"total_amount": 0.0, "total_items": 0}
                user_data[user]["total_amount"] += amount
                user_data[user]["total_items"] += items

                # Count tags
                for tag in tags:
                    tag_counts[tag] = tag_counts.get(tag, 0) + 1
            except json.JSONDecodeError:
                continue

# Prepare top_5_users_by_amount
# Sort users by total_amount descending
user_list = []
for user, data in user_data.items():
    user_list.append({
        "user": user,
        "total_amount": data["total_amount"],
        "total_items": data["total_items"]
    })

# Sort by total_amount descending
user_list.sort(key=lambda x: x["total_amount"], reverse=True)
top_5_users = []
for i in range(min(5, len(user_list))):
